# Multi-attribute sorting using key function tuples
students = [
    {"name": "Alice", "gpa": 3.8, "age": 22},
    {"name": "Bob", "gpa": 3.9, "age": 20},
    {"name": "Charlie", "gpa": 3.8, "age": 20}
]

# Sort by GPA descending (-gpa), then by age ascending (age)
students.sort(key=lambda s: (-s["gpa"], s["age"]))
for s in students:
    print(f"{s['name']}: GPA {s['gpa']}, Age {s['age']}")

# Interval merging pattern
def merge_intervals(intervals):
    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

print(merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]))
